// WF-11 | Stage 2 - Data Processing
// Turns the input of BOTH triggers (weekly schedule / manual webhook) into one envelope.
// ===================================================================================
//  CẤU HÌNH TẬP TRUNG - chỉ cần sửa ở khối CONFIG này
// ===================================================================================
const CONFIG = {
  days: 7,                 // chỉ lấy tin trong N ngày gần nhất (1-30)
  maxPerCompetitor: 5,     // tối đa N bài mỗi đối thủ (1-10)
  maxCompetitors: 8,       // tối đa số đối thủ mỗi lần chạy
  // Google News: en-US cho nhiều tin quốc tế; đổi thành hl:'vi', gl:'VN', ceid:'VN:vi' để lấy tin tiếng Việt
  news: { hl: 'en-US', gl: 'US', ceid: 'US:en' },
  // Danh sách đối thủ mặc định (khi lịch tự chạy hoặc webhook không gửi competitors)
  competitors: [
    { name: 'HubSpot', keywords: ['HubSpot CRM'] },
    { name: 'Salesforce', keywords: ['Salesforce Agentforce'] },
    { name: 'Zoho CRM', keywords: [] },
    { name: 'Pipedrive', keywords: [] },
    { name: 'GetFly CRM', keywords: ['GetFly'] },
  ],
};
// ===================================================================================
const DEFAULT_ORG_ID = '11111111-1111-4111-8111-111111111111';
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = (Math.random() * 16) | 0;
  return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
});

let trigger = 'schedule';
try { if ($('01b Webhook Manual Run').isExecuted) trigger = 'webhook'; } catch (e) { /* ignore */ }

const raw = $json;
const b = trigger === 'webhook' ? (raw.body || {}) : {};
const h = trigger === 'webhook' ? (raw.headers || {}) : {};
const errors = [];

let organizationId = String(b.organizationId || DEFAULT_ORG_ID).trim();
if (!UUID_RE.test(organizationId)) {
  errors.push({ field: 'organizationId', code: 'INVALID_UUID', message: 'organizationId must be a UUID' });
  organizationId = DEFAULT_ORG_ID;
}
let correlationId = String(h['x-correlation-id'] || b.correlationId || '').trim();
if (!UUID_RE.test(correlationId)) correlationId = uuid();

const intIn = (v, def, min, max, field) => {
  if (v === undefined || v === null || v === '') return def;
  const n = Number(v);
  if (!Number.isInteger(n) || n < min || n > max) {
    errors.push({ field, code: 'OUT_OF_RANGE', message: field + ' must be an integer from ' + min + ' to ' + max });
    return def;
  }
  return n;
};
const days = intIn(b.days, CONFIG.days, 1, 30, 'days');
const maxPerCompetitor = intIn(b.maxPerCompetitor, CONFIG.maxPerCompetitor, 1, 10, 'maxPerCompetitor');
const force = b.force === true;

const rawList = Array.isArray(b.competitors) && b.competitors.length ? b.competitors : CONFIG.competitors;
if (rawList.length > CONFIG.maxCompetitors) {
  errors.push({ field: 'competitors', code: 'TOO_MANY', message: 'at most ' + CONFIG.maxCompetitors + ' competitors per run' });
}
const competitors = [];
rawList.slice(0, CONFIG.maxCompetitors).forEach((c, i) => {
  const o = typeof c === 'string' ? { name: c, keywords: [] } : (c || {});
  const name = String(o.name || '').replace(/"/g, '').trim().slice(0, 80);
  if (!name) { errors.push({ field: 'competitors[' + i + '].name', code: 'REQUIRED', message: 'name is required' }); return; }
  const kws = (Array.isArray(o.keywords) ? o.keywords : []).map((k) => String(k).replace(/"/g, '').trim().slice(0, 80)).filter(Boolean).slice(0, 4);
  const terms = [name, ...kws].filter((v, idx, arr) => arr.indexOf(v) === idx);
  competitors.push({ name, keywords: kws, query: '(' + terms.map((t) => '"' + t + '"').join(' OR ') + ')' });
});
if (competitors.length === 0 && errors.length === 0) errors.push({ field: 'competitors', code: 'REQUIRED', message: 'at least one competitor is required' });

return {
  json: {
    valid: errors.length === 0,
    errors,
    trigger,
    organizationId,
    correlationId,
    force,
    days,
    maxPerCompetitor,
    news: CONFIG.news,
    competitors,
    runInput: { trigger, competitors: competitors.map((c) => c.name), days, maxPerCompetitor, force },
  },
};

