// WF-11 | Stage 2 - Data Processing: one Google News RSS request per competitor.
const cfg = $('02 Normalize Input').first().json;
return cfg.competitors.map((c) => {
  const q = encodeURIComponent(c.query + ' when:' + cfg.days + 'd');
  const url = 'https://news.google.com/rss/search?q=' + q +
    '&hl=' + encodeURIComponent(cfg.news.hl) + '&gl=' + encodeURIComponent(cfg.news.gl) +
    '&ceid=' + encodeURIComponent(cfg.news.ceid);
  return { json: { competitorName: c.name, url } };
});

// WF-11 | Stage 2 - Data Processing: parse RSS XML -> clean article list per competitor.
const cfg = $('02 Normalize Input').first().json;
const reqs = $('06 Build Feed Requests').all();

const decode = (s) => String(s || '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/&#39;|&apos;/g, "'").replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const strip = (s) => decode(s).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const tag = (blk, t) => {
  const m = blk.match(new RegExp('<' + t + '(?:\\s[^>]*)?>([\\s\\S]*?)</' + t + '>', 'i'));
  return m ? m[1] : '';
};
const cutoff = Date.now() - cfg.days * 86400000;

const competitors = [];
const feedErrors = [];
$input.all().forEach((it, i) => {
  const idx = it.pairedItem && Number.isInteger(it.pairedItem.item) ? it.pairedItem.item : i;
  const name = (reqs[idx] && reqs[idx].json.competitorName) || cfg.competitors[idx].name;
  const rawBody = it.json.body !== undefined ? it.json.body : it.json.data;
  const body = typeof rawBody === 'string' ? rawBody : '';
  const status = it.json.statusCode;
  const blocks = body.match(/<item>[\s\S]*?<\/item>/gi) || [];

  if (it.json.error || (status && status !== 200) || (!blocks.length && !/<rss|<channel/i.test(body))) {
    feedErrors.push({ competitor: name, statusCode: status || null, message: String((it.json.error && it.json.error.message) || it.json.error || 'feed not readable').slice(0, 200) });
    competitors.push({ name, articles: [] });
    return;
  }

  const seen = new Set();
  const articles = [];
  for (const blk of blocks) {
    let title = strip(tag(blk, 'title'));
    const source = strip(tag(blk, 'source'));
    if (source && title.endsWith(' - ' + source)) title = title.slice(0, -(source.length + 3)).trim();
    const url = decode(tag(blk, 'link')).trim();
    const t = new Date(decode(tag(blk, 'pubDate')).trim()).getTime();
    if (!title || !url || !Number.isFinite(t) || t < cutoff) continue;
    const key = title.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
    if (seen.has(key)) continue;
    seen.add(key);
    articles.push({ title: title.slice(0, 300), source: source.slice(0, 80), publishedAt: new Date(t).toISOString(), url, _t: t });
  }
  articles.sort((a, b2) => b2._t - a._t);
  competitors.push({ name, articles: articles.slice(0, cfg.maxPerCompetitor).map(({ _t, ...rest }) => rest) });
});

// stable ids A1, A2... (the AI cites ids, never URLs, so it cannot invent links)
let n = 0;
competitors.forEach((c) => c.articles.forEach((a) => { n += 1; a.id = 'A' + n; }));

// fingerprint of the input: same headlines => same hash => no need to pay for the AI again
const hash = (str) => {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0');
};
const fp = competitors.map((c) => c.name + '|' + c.articles.map((a) => a.url).sort().join(',')).join('\n');

return { json: { competitors, totalArticles: n, feedErrors, inputHash: hash(fp) } };

// WF-11 | Stage 7 - Decision: analyse only when there is something new.
const d = $json;
const cfg = $('02 Normalize Input').first().json;
const ctx = $('05 Load Context').first().json;

if (d.totalArticles === 0 && d.feedErrors.length >= cfg.competitors.length) {
  throw new Error('ALL_FEEDS_FAILED: ' + JSON.stringify(d.feedErrors).slice(0, 400));
}
let skipReason = null;
if (d.totalArticles === 0) skipReason = 'NO_NEWS';
else if (!cfg.force && ctx.last_hash && ctx.last_hash === d.inputHash) skipReason = 'NO_NEW_ARTICLES';

return { json: { ...d, skipReason, shouldAnalyze: skipReason === null, lastReportId: ctx.last_report_id || null } };

