// WF-11 | Stage 8 - Transformation: build the body for POST /events (event_outbox).
const d = $('02 Normalize Input').first().json;
const r = $('12 Parse AI Report').first().json;
const high = r.report.competitors.filter((c) => c.threatLevel === 'HIGH').map((c) => c.name);

return { json: { eventBody: {
  eventName: 'competitor.report.generated',
  aggregateType: 'document',
  aggregateId: $json.id,
  organizationId: d.organizationId,
  correlationId: d.correlationId,
  payload: {
    schemaVersion: 1,
    workflow: 'WF-11',
    documentId: $json.id,
    fileName: r.fileName,
    title: r.title,
    trigger: d.trigger,
    period: r.report.period,
    competitorCount: r.report.competitors.length,
    articleCount: r.articleCount,
    overallThreat: r.overallThreat,
    highThreatCompetitors: high,
    model: r.model,
  },
} } };

